// designer-bakeoff.mjs — MERIT-ONLY seat benchmark for the Web Designer seat.
// Owner law 2026-10-26 #docneural-site: "Always hire one that is best at its
// work. Don't bias to GLM. You should hire based on capabilities and
// performance."
//
// Protocol (standing, blind, reproducible):
//   1. Deterministic planted-defect screenshot (task A) — 5 known defects,
//      3 intentional decoys. Generated by gen_planted_shot() in Python/PIL.
//   2. Real-shot critique (task B) — deployed home + graph screenshots.
//   3. Candidates run under BLIND codes (A, B, C...). The code->model key is
//      written to KEY.json and not printed until scoring is filed.
//   4. Fixed rubric, max 9 pts:
//        task A recall: 1 pt per planted defect (type + region correct), max 5
//        task A false positives on intentional decoys: -0.5 each
//        task A fix actionability: 0-2
//        task B critique specificity: 0-2 (hex/px + element = 2)
//      Latency recorded per task, tie-breaker only.
//
// Usage: node designer-bakeoff.mjs <shotA.png> <shotB-home.png> <shotB-graph.png> <outdir> [model...]
//   - Generates <outdir>/planted-shot.png
//   - Runs each model under a blind code; writes <code>-A.txt, <code>-B.txt, KEY.json, RESULTS.json
//
// Known planted defects (scorer's checklist — DO NOT show to candidates):
//   D1 low-contrast body text  (#3f4650 on #14181f panel A, ratio ~1.6:1)
//   D2 button overlaps headline text (panel B, "SYNAPSES" clipped by CTA)
//   D3 nav item 3 ("MANUALS") drawn 8px below its siblings
//   D4 chip "#guix" red (#ff0033) where siblings are cyan (#00e5ff)
//   D5 stat "MEMBERS 9,4" clipped at the right image edge
// Intentional decoys (flagging these costs precision):
//   I1 chromatic aberration on the wordmark (2px RGB split)
//   I2 full-screen scanlines (alpha 0.04)
//   I3 decorative glow bloom bottom-left

import fs from 'node:fs';
import path from 'node:path';
import { execSync } from 'node:child_process';

const [shotA, homeAfter, graphAfter, outdir, ...models] = process.argv.slice(2);
if (!shotA || !homeAfter || !graphAfter || !outdir || models.length === 0) {
  console.error('usage: node designer-bakeoff.mjs <outA.png> <homeAfter.png> <graphAfter.png> <outdir> <model> [model...]');
  process.exit(1);
}
fs.mkdirSync(outdir, { recursive: true });

// ---------------------------------------------------------------- image gen
function genPlantedShot(dest) {
  execSync(`python3 - "${dest}" <<'PYEOF'
import sys
from PIL import Image, ImageDraw, ImageFont

dest = sys.argv[1]
W, H = 1280, 800
bg = (5, 7, 13)
im = Image.new('RGB', (W, H), bg)
d = ImageDraw.Draw(im)

mono  = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf', 18)
monoS = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf', 14)
big   = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 64)
mid   = ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf', 30)

CYAN = (0, 229, 255); VIOLET = (120, 80, 255); MUT = (63, 70, 80)
PANEL = (20, 24, 31); RED = (255, 0, 51); ACID = (57, 255, 20)

# grid (subtle)
for x in range(0, W, 40): d.line([(x, 0), (x, H)], fill=(14, 18, 28), width=1)
for y in range(0, H, 40): d.line([(0, y), (W, y)], fill=(14, 18, 28), width=1)

# nav — D3: third item 8px low
d.text((60, 32), 'DOCS', font=mono, fill=CYAN)
d.text((150, 32), 'SYNAPSES', font=mono, fill=CYAN)
d.text((290, 40), 'MANUALS', font=mono, fill=CYAN)   # +8px
d.text((430, 32), 'ABOUT', font=mono, fill=CYAN)

# wordmark with chromatic aberration (I1)
def wordmark(x, y):
    d.text((x+2, y), 'DOCNEURAL', font=big, fill=RED)
    d.text((x-2, y+2), 'DOCNEURAL', font=big, fill=CYAN)
    d.text((x, y+1), 'DOCNEURAL', font=big, fill=(180, 160, 255))
wordmark(60, 120)

# panel A — D1: body text #3f4650 on PANEL (~1.6:1)
d.rounded_rectangle([60, 260, 580, 480], 8, fill=PANEL, outline=(30, 40, 55), width=2)
d.text((84, 284), 'Technical manuals, wired as synapses.', font=mono, fill=MUT)
d.text((84, 316), 'Every node is a page. Every wire is a link.', font=mono, fill=MUT)
d.text((84, 348), 'Browse in the reader or roam the graph.', font=mono, fill=MUT)
d.text((84, 380), 'Built for depth, tuned for the dark.', font=mono, fill=MUT)

# panel B — D2: button overlaps the SYNAPSES headline
d.rounded_rectangle([640, 260, 1220, 480], 8, fill=PANEL, outline=(30, 40, 55), width=2)
d.text((664, 284), 'SYNAPSES 30,915 wires live', font=mid, fill=CYAN)
d.rounded_rectangle([900, 300, 1140, 356], 6, fill=(40, 8, 20), outline=RED, width=2)
d.text((944, 318), 'ENTER GRAPH', font=mono, fill=RED)

# stat row — D5: 4th stat clipped at right edge
d.text((60, 560), 'NODES 1386', font=mono, fill=CYAN)
d.text((260, 560), 'WIRES 30915', font=mono, fill=CYAN)
d.text((480, 560), 'SOURCES 3', font=mono, fill=CYAN)
d.text((700, 560), 'MEMBERS 9,412 SEATS 27', font=mono, fill=CYAN)  # runs past 1280? no -> force clip:
d.text((1100, 560), 'MEMBERS 9,4', font=mono, fill=CYAN)           # right edge cuts at '9,4'

# chips — D4: '#guix' red among cyan siblings
chips = [('#emacs', 60), ('#org', 170), ('#guix', 280)]
for label, x in chips:
    col = RED if label == '#guix' else CYAN
    w = 14 * len(label) + 24
    d.rounded_rectangle([x, 650, x + w, 690], 19, outline=col, width=2)
    d.text((x + 12, 660), label, font=monoS, fill=col)

# glow bloom (I3)
glow = Image.new('L', (W, H), 0)
gd = ImageDraw.Draw(glow)
gd.ellipse([80, 560, 420, 780], fill=26)
im = Image.composite(Image.new('RGB', (W, H), (0, 120, 160)), im, glow)
d = ImageDraw.Draw(im)

# scanlines (I2)
for y in range(0, H, 4):
    d.line([(0, y), (W, y)], fill=(10, 12, 18), width=1)

im.save(dest)
print('planted shot ->', dest)
PYEOF`);
}
const plantedPath = path.join(outdir, 'planted-shot.png');
genPlantedShot(plantedPath);

// ---------------------------------------------------------------- lanes
const cfg = JSON.parse(fs.readFileSync('/etc/.z-ai-config', 'utf8'));
const gatewayHeaders = {
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${cfg.apiKey}`,
  'X-Z-AI-From': 'Z',
  ...(cfg.chatId ? { 'X-Chat-Id': cfg.chatId } : {}),
  ...(cfg.userId ? { 'X-User-Id': cfg.userId } : {}),
  ...(cfg.token ? { 'X-Token': cfg.token } : {}),
};

const b64 = (p) => `data:image/png;base64,${fs.readFileSync(p).toString('base64')}`;

async function callVision(model, content) {
  const t0 = Date.now();
  const res = await fetch(`${cfg.baseUrl}/chat/completions/vision`, {
    method: 'POST',
    headers: gatewayHeaders,
    body: JSON.stringify({
      model,
      messages: [{ role: 'user', content }],
      thinking: { type: 'disabled' },
    }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${(await res.text()).slice(0, 200)}`);
  const j = await res.json();
  return { text: j.choices?.[0]?.message?.content ?? '(no content)', echo: j.model, ms: Date.now() - t0 };
}

const promptA = `You are a senior UI design QA reviewer. This is a screenshot of a dark sci-fi/cyberpunk landing page (1280x800).

List EVERY visual DEFECT you can find. For each defect, exactly one line:
- WHAT is wrong (name the element/text) | WHERE (top/mid/bottom + which panel/row) | FIX (one concrete line: color in hex or size in px)

After the defect list, a section "INTENTIONAL": unusual-but-deliberate design elements you can see, one per line.
Do not invent defects; accuracy beats volume.`;

const promptB = `Design review of a deployed dark cyberpunk docs site. IMAGE 1 = home. IMAGE 2 = its org-roam graph view.
Rank the TOP 3 highest-impact visual fixes. For each: WHAT, WHERE, exact treatment (colors in hex, sizes in px). No preamble.`;

// ---------------------------------------------------------------- run
const shuffled = [...models];
// Fisher-Yates with a fixed-ish seed from process env for reproducibility
let seed = parseInt(process.env.BENCH_SEED || '1026', 10);
const rnd = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
for (let i = shuffled.length - 1; i > 0; i--) {
  const j = Math.floor(rnd() * (i + 1));
  [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
}
const letters = 'ABCDEFGH';
const key = {};
const results = [];

for (let i = 0; i < shuffled.length; i++) {
  const code = letters[i];
  const model = shuffled[i];
  key[code] = model;
  console.log(`candidate ${code}: running (model hidden)...`);
  try {
    const A = await callVision(model, [
      { type: 'image_url', image_url: { url: b64(plantedPath) } },
      { type: 'text', text: promptA },
    ]);
    fs.writeFileSync(path.join(outdir, `${code}-A.txt`), `${A.text}\n\n[echo=${A.echo} latency=${A.ms}ms]\n`);
    const B = await callVision(model, [
      { type: 'image_url', image_url: { url: b64(homeAfter) } },
      { type: 'image_url', image_url: { url: b64(graphAfter) } },
      { type: 'text', text: promptB },
    ]);
    fs.writeFileSync(path.join(outdir, `${code}-B.txt`), `${B.text}\n\n[echo=${B.echo} latency=${B.ms}ms]\n`);
    results.push({ code, model, aMs: A.ms, bMs: B.ms, echo: A.echo, ok: true });
    console.log(`candidate ${code}: A=${A.ms}ms B=${B.ms}ms ok`);
  } catch (e) {
    results.push({ code, model, ok: false, error: String(e.message).slice(0, 200) });
    console.log(`candidate ${code}: FAILED ${String(e.message).slice(0, 120)}`);
  }
}

fs.writeFileSync(path.join(outdir, 'KEY.json'), JSON.stringify(key, null, 2));
fs.writeFileSync(path.join(outdir, 'RESULTS.json'), JSON.stringify(results, null, 2));
console.log('done. blind codes:', Object.keys(key).join(','), '-> KEY.json (unblind after scoring is filed)');
